/* ==========================================================================
   Emergency Management (specification module 14)
   Per branch, the emergency arrangements in one place:
   - emergency scenarios, the emergency response plan, evacuation procedure
     and map (linked from the Document Manager or uploaded), assembly points
     and emergency contacts;
   - the emergency team: people with an active fire marshal or first aider
     appointment (People), plus their emergency training status (Training);
   - fire and first aid equipment from Assets & Equipment, with its
     inspection status (no second register);
   - drills: schedule, record the result (evacuation time, people,
     observations) and turn findings into corrective actions.
   ========================================================================== */
'use strict';

const canEm = () => can('emergency.manage');
const emOf = sid => (S.emergency || []).find(e => e.site === sid);
const drills = () => (S.drills || []).filter(d => d.org === S.ui.org && inSite(d, S.ui.site));
const lastDrill = sid => (S.drills || []).filter(d => d.site === sid && d.status === 'Completed').sort((a, b) => b.held.localeCompare(a.held))[0] || null;
function drillDue(sid) { const e = emOf(sid), l = lastDrill(sid), months = (e && e.drillMonths) || 12; return l ? addMonths(l.held, months) : TODAY; }
const emEquip = sid => S.assets.filter(a => a.site === sid && a.status !== 'Decommissioned' && (a.type === 'AT-FIRE' || /first aid|extinguisher|hose reel|fire/i.test(a.name)));
const equipOk = a => assetChecks(a).every(Boolean);
function emTeam(sid) { return (S.appointments || []).filter(a => a.site === sid && ['AT-FIRE', 'AT-FIRST'].includes(a.type) && ['Active', 'Accepted', 'Uploaded'].includes(typeof aptStatus === 'function' ? aptStatus(a) : a.status)); }
function emGaps(sid) { const e = emOf(sid) || {}, g = []; if (!e.plan) g.push('No emergency response plan'); if (!e.evacProc && !e.evacMap) g.push('No evacuation procedure or map'); if (!(e.assembly || []).length) g.push('No assembly point');
  if (daysTo(drillDue(sid)) < 0) g.push('Drill overdue'); if (!emTeam(sid).some(a => a.type === 'AT-FIRE')) g.push('No fire marshal appointed'); if (!emTeam(sid).some(a => a.type === 'AT-FIRST')) g.push('No first aider appointed'); if (emEquip(sid).some(a => !equipOk(a))) g.push('Emergency equipment not in order'); return g; }

ROUTES.emergency = (p, q = {}) => {
  if (p[0] && /^DRL-/.test(p[0])) return drillDetail(p[0]);
  const sites = orgSites().filter(s => S.ui.site === 'ALL' || s.id === S.ui.site), tab = p[0] === 'drills' ? 'drills' : (p[0] && byId('sites', p[0]) ? p[0] : 'overview');
  const D = drills(), openF = D.reduce((n, d) => n + (d.findings || []).filter(f => f.action && actionOpen(byId('actions', f.action) || {})).length, 0);
  const tabs = [['overview', 'Branches']].concat(sites.map(s => [s.id, s.short || s.name])).concat([['drills', 'Drills', D.filter(d => d.status === 'Scheduled').length || '']]);
  let body = '';
  if (tab === 'overview') body = `<div class="card"><div class="card-body flush"><div class="table-wrap"><table class="tbl stackable"><thead><tr><th>Branch</th><th>Plan</th><th>Assembly points</th><th>Emergency team</th><th>Equipment</th><th>Last drill</th><th>Next drill due</th><th>Gaps</th></tr></thead><tbody>${sites.map(s => { const e = emOf(s.id) || {}, l = lastDrill(s.id), eq = emEquip(s.id), g = emGaps(s.id);
    return `<tr class="rowlink" data-href="#/emergency/${s.id}"><td data-label="Branch"><b>${esc(s.name)}</b></td><td data-label="Plan">${e.plan ? `<span class="mono">${esc((byId('documents', e.plan) || {}).number || '')}</span>` : '<span class="due red">None</span>'}</td><td data-label="Assembly">${(e.assembly || []).length || '<span class="due red">0</span>'}</td><td data-label="Team">${emTeam(s.id).length}</td><td data-label="Equipment">${eq.length ? `${eq.filter(equipOk).length} of ${eq.length} in order` : '—'}</td><td data-label="Last drill">${l ? fmt(l.held) : '—'}</td><td data-label="Next drill">${dueText(drillDue(s.id))}</td><td data-label="Gaps">${g.length ? g.map(t => badge(t, 'amber', true)).join(' ') : badge('In order', 'green', true)}</td></tr>`; }).join('')}</tbody></table></div></div></div>`;
  if (tab === 'overview') { const s0 = sites[0], step = (n, t, d, href, lbl) => `<li><span class="em-n">${n}</span><div><b>${t}</b><small>${d}</small>${href ? `<a href="${href}">${lbl} →</a>` : ''}</div></li>`;
    body = `<div class="card em-guide"><div class="card-head"><h2>What this module does</h2><span class="ch-sub">Being ready for an emergency at each branch, and proving it with drills</span></div><div class="card-body"><ol class="em-steps">
      ${step(1, 'Set up each branch\'s arrangements', 'Emergency scenarios (fire, gas leak, bomb threat…), the emergency response plan and evacuation procedure/map from the Document Manager, assembly points and emergency contacts.', s0 ? '#/emergency/' + s0.id : '', 'Open ' + esc(s0 ? s0.short || s0.name : ''))}
      ${step(2, 'Know your emergency team', 'Fire marshals and first aiders come from their appointments in People, with their emergency training status. A branch without one is flagged.', '#/people/appointments', 'Appointments')}
      ${step(3, 'Keep emergency equipment in order', 'Fire extinguishers, hose reels and first aid boxes come from Assets & Equipment, with their inspection status. Nothing is captured twice.', '#/assets', 'Equipment')}
      ${step(4, 'Hold and record drills', 'Schedule a drill, record the evacuation time, people evacuated and observations, and turn findings into corrective actions. The next drill falls due automatically.', '#/emergency/drills', 'Drills')}
    </ol><p class="t-sub" style="margin:10px 0 0">Anything missing (no plan, no assembly point, no fire marshal or first aider, equipment not in order, drill overdue) shows as a gap below, on the dashboard and in the compliance figures. Open a branch to see and fix its arrangements.</p></div></div>` + body; }
  else if (tab === 'drills') body = drillsHtml(D);
  else body = emSiteHtml(byId('sites', tab));
  const fab = canEm() ? (tab === 'drills' || tab === 'overview' ? fabBtn('drillNew', 'Schedule a drill') : fabStack([{ act: 'drillNew', label: 'Schedule a drill', attrs: `data-site="${tab}"` }, { act: 'emEdit', label: 'Edit arrangements', icon: 'edit', cls: 'ghost', attrs: `data-site="${tab}"` }])) : '';
  const html = `${pageHead('Emergency management', 'Emergency plans, evacuation, assembly points, contacts, the emergency team, emergency equipment and drills for each branch.', '', scopePill())}${fab}
    <div class="kpis">${kpi('Branches with gaps', sites.filter(s => emGaps(s.id).length).length, `of ${sites.length} branch(es)`, sites.some(s => emGaps(s.id).length) ? 'amber' : 'green', '#/emergency', 'siren')}
      ${kpi('Drills overdue', sites.filter(s => daysTo(drillDue(s.id)) < 0).length, `${D.filter(d => d.status === 'Scheduled').length} scheduled`, sites.some(s => daysTo(drillDue(s.id)) < 0) ? 'red' : 'green', '#/emergency/drills', 'clock')}
      ${kpi('Open drill findings', openF, 'Corrective actions not yet verified', openF ? 'amber' : 'green', '#/actions?source=Emergency%20drill', 'target')}
      ${kpi('Emergency equipment not in order', sites.reduce((n, s) => n + emEquip(s.id).filter(a => !equipOk(a)).length, 0), 'Inspection overdue, certificate or defect', 'amber', '#/assets', 'flame')}</div>
    ${tabsHtml('#/emergency', tabs, tab)}${body}`;
  return { title: 'Emergency management', nav: 'emergency', crumbs: [['Emergency Management', '#/emergency']], html };
};
function emSiteHtml(s) { const e = emOf(s.id) || {}, doc = id => { const d = byId('documents', id); return d ? `<a href="#/documents/${d.id}">${esc(d.number)} — ${esc(d.title)}</a>` : '—'; }, g = emGaps(s.id), team = emTeam(s.id);
  const trn = x => { if (typeof trStatus !== 'function') return ''; const c = (S.courses || []).filter(c => c.org === s.org && c.category === 'Emergency'), need = typeof requiredFor === 'function' ? requiredFor(person(x)).filter(r => c.some(cc => cc.id === r.course)) : []; return need.map(r => badge(`${byId('courses', r.course).short || byId('courses', r.course).name}: ${trStatus(x, r.course)}`, TR_TONE[trStatus(x, r.course)], true)).join(' '); };
  return `${g.length ? `<div class="alert warn">${icon('alert')}<div><b>Gaps at ${esc(s.short || s.name)}:</b> ${g.map(esc).join(' · ')}</div></div>` : ''}
  ${canEm() ? `<div class="btn-row mb"><button class="btn primary" data-act="emEdit" data-site="${s.id}">${icon('edit', 'sm')} Edit arrangements</button><button class="btn" data-act="drillHeld" data-site="${s.id}">${icon('plus', 'sm')} Record a drill already held</button><button class="btn" data-act="drillNew" data-site="${s.id}">${icon('clock', 'sm')} Schedule a drill</button></div>` : ''}<div class="grid g2"><div class="card"><div class="card-head"><h2>Plans and procedures</h2></div><div class="card-body"><div class="kv"><div>Emergency response plan</div><div>${e.plan ? doc(e.plan) : '<span class="due red">Not linked</span>'}</div><div>Evacuation procedure</div><div>${e.evacProc ? doc(e.evacProc) : '—'}</div><div>Evacuation map</div><div>${e.evacMap ? `<button type="button" class="link-btn" ${fileAttrs(e.evacMap)}>${esc(e.evacMap.name)}</button>` : '—'}</div><div>Drill every</div><div>${e.drillMonths || 12} months</div></div></div></div>
    <div class="card"><div class="card-head"><h2>Scenarios</h2></div><div class="card-body">${(e.scenarios || []).length ? `<ul class="plain-list">${e.scenarios.map(x => `<li>${esc(x)}</li>`).join('')}</ul>` : '<p class="muted">No scenarios recorded.</p>'}</div></div>
    <div class="card"><div class="card-head"><h2>Assembly points</h2></div><div class="card-body">${(e.assembly || []).length ? `<ul class="plain-list">${e.assembly.map(x => `<li>${esc(x)}</li>`).join('')}</ul>` : '<span class="due red">None recorded.</span>'}</div></div>
    <div class="card"><div class="card-head"><h2>Emergency contacts</h2></div><div class="card-body flush">${(e.contacts || []).length ? `<ul class="link-list">${e.contacts.map(c => `<li><div class="ll-main"><b>${esc(c.name)}</b><div class="t-sub">${esc(c.role || '')}</div></div><span class="mono">${esc(c.number)}</span></li>`).join('')}</ul>` : '<div class="card-body muted">None recorded.</div>'}</div></div>
    <div class="card"><div class="card-head"><h2>Emergency team</h2><span class="ch-sub">From appointments in People</span></div><div class="card-body flush">${team.length ? `<ul class="link-list">${team.map(a => `<li><div class="ll-main"><a href="#/people/${a.person}"><b>${esc(pname(a.person))}</b></a><div class="t-sub">${esc(aptType(a).name)}</div></div><div>${trn(a.person)}</div></li>`).join('')}</ul>` : '<div class="card-body"><span class="due red">No fire marshals or first aiders appointed.</span></div>'}</div></div>
    <div class="card"><div class="card-head"><h2>Emergency equipment</h2><span class="ch-sub">From Assets & Equipment</span></div><div class="card-body flush">${emEquip(s.id).length ? `<ul class="link-list">${emEquip(s.id).map(a => `<li><div class="ll-main"><a href="#/assets/${a.id}"><b>${esc(a.tag)}</b> ${esc(a.name)}</a><div class="t-sub">${esc(a.location || '')}</div></div>${equipOk(a) ? badge('In order', 'green', true) : badge('Needs attention', 'red', true)}</li>`).join('')}</ul>` : '<div class="card-body muted">No fire or first aid equipment registered as assets.</div>'}</div></div></div>`; }
ACT.emEdit = (el) => { const sid = el.dataset.site, e = emOf(sid) || { site: sid, org: siteOrgOf(sid) }, docs = S.documents.filter(d => inSite(d, 'ALL')).map(d => ({ value: d.id, label: `${d.number} — ${d.title}` }));
  openModal({ title: `Emergency arrangements — ${sname(sid)}`, size: 'wide', body: `<div class="form-grid">${fld({ name: 'plan', label: 'Emergency response plan', type: 'select', options: opts(docs, e.plan || '', '— Not linked —'), full: true })}${fld({ name: 'evacProc', label: 'Evacuation procedure', type: 'select', options: opts(docs, e.evacProc || '', '— Not linked —'), full: true })}${fld({ name: 'evacMap', label: 'Evacuation map (image or PDF)', type: 'file', full: true })}
    ${fld({ name: 'scenarios', label: 'Emergency scenarios (one per line)', type: 'textarea', rows: 4, value: (e.scenarios || []).join('\n'), full: true })}${fld({ name: 'assembly', label: 'Assembly points (one per line)', type: 'textarea', rows: 2, value: (e.assembly || []).join('\n'), full: true })}
    ${fld({ name: 'contacts', label: 'Emergency contacts — one per line: name; role; number', type: 'textarea', rows: 4, value: (e.contacts || []).map(c => [c.name, c.role, c.number].join('; ')).join('\n'), full: true })}${fld({ name: 'drillMonths', label: 'Hold a drill every (months)', type: 'number', min: 1, value: e.drillMonths || 12 })}</div>`,
    buttons: [{ label: 'Save', cls: 'primary', onClick: m => { const v = readForm(m), lines = t => (t || '').split('\n').map(x => x.trim()).filter(Boolean);
      Object.assign(e, { plan: v.plan || null, evacProc: v.evacProc || null, scenarios: lines(v.scenarios), assembly: lines(v.assembly), contacts: lines(v.contacts).map(l => { const [name, role, number] = l.split(';').map(x => (x || '').trim()); return { name, role, number: number || role || '' }; }), drillMonths: Math.max(1, +v.drillMonths || 12) }); if (v.evacMap) e.evacMap = v.evacMap;
      S.emergency = S.emergency || []; if (!S.emergency.includes(e)) S.emergency.push(e); log(`Updated emergency arrangements for ${sname(sid)}`, '#/emergency/' + sid); save(); rerender(); } }] }); };
const drillBtns = (sid) => canEm() ? `<div class="btn-row"><button class="btn sm primary" data-act="drillHeld"${sid ? ` data-site="${sid}"` : ''}>${icon('plus', 'sm')} Record a drill already held</button><button class="btn sm" data-act="drillNew"${sid ? ` data-site="${sid}"` : ''}>${icon('clock', 'sm')} Schedule a drill</button></div>` : '';
function drillsHtml(D) { if (!D.length) return `<div class="card"><div class="card-head"><h2>Drills</h2>${drillBtns()}</div>${emptyList('No drills yet.')}</div>`;
  return `<div class="card"><div class="card-head"><h2>Drills</h2><span class="ch-sub">Open a scheduled drill to record its result</span>${drillBtns()}</div><div class="card-body flush"><div class="table-wrap"><table class="tbl stackable"><thead><tr><th>Drill</th><th>Branch</th><th>Date</th><th>Evacuation time</th><th>People</th><th>Findings</th><th>Status</th></tr></thead><tbody>${D.sort((a, b) => (b.held || b.date).localeCompare(a.held || a.date)).map(d => `<tr class="rowlink" data-href="#/emergency/${d.id}"><td data-label="Drill"><span class="mono">${d.id}</span><div class="t-title">${esc(d.scenario)}</div></td><td data-label="Branch">${esc(sname(d.site))}</td><td data-label="Date">${d.status === 'Scheduled' ? dueText(d.date) : fmt(d.held)}</td><td data-label="Time">${d.evacMinutes ? d.evacMinutes + ' min' : '—'}</td><td data-label="People">${d.people || '—'}</td><td data-label="Findings">${(d.findings || []).length || '—'}</td><td data-label="Status">${badge(d.status, d.status === 'Completed' ? 'green' : 'blue')}</td></tr>`).join('')}</tbody></table></div></div></div>`; }
function drillDetail(id) { const d = byId('drills', id); if (!d || d.org !== S.ui.org) return ROUTES.notfound();
  const html = `<div class="status-hero"><div><div class="sh-id">${d.id} · ${esc(sname(d.site))}</div><h1 style="margin:2px 0 6px">${esc(d.scenario)}</h1>${badge(d.status, d.status === 'Completed' ? 'green' : 'blue')}</div><div class="sh-actions">${canEm() && d.status === 'Scheduled' ? `<button class="btn primary" data-act="drillResult" data-id="${d.id}">Record result</button>` : ''}</div></div>
  <div class="detail"><div class="stack"><div class="card"><div class="card-head"><h2>Result</h2></div><div class="card-body">${d.status === 'Completed' ? `<div class="kv"><div>Held</div><div>${fmt(d.held)}</div><div>Evacuation time</div><div>${d.evacMinutes} minutes${d.target ? ` (target ${d.target} min)` : ''}</div><div>People evacuated</div><div>${d.people}</div><div>Observations</div><div>${esc(d.observations || '—')}</div></div>${(d.files || []).length ? d.files.map(f => `<button type="button" class="link-btn" ${fileAttrs(f)}>${esc(f.name)}</button>`).join(', ') : ''}` : `<p>Scheduled for ${fmt(d.date)}.</p>`}</div></div>
    <div class="card"><div class="card-head"><h2>Findings</h2></div><div class="card-body flush">${(d.findings || []).length ? `<ul class="link-list">${d.findings.map(f => `<li><div class="ll-main">${esc(f.text)}</div>${f.action ? `<a href="#/actions/${f.action}" class="mono">${f.action}</a> ${sbadge((byId('actions', f.action) || {}).status)}` : ''}</li>`).join('')}</ul>` : '<div class="card-body muted">None.</div>'}</div></div></div>
  <div class="stack"><div class="card"><div class="card-head"><h2>Details</h2></div><div class="card-body"><div class="kv"><div>Coordinator</div><div>${esc(pname(d.coordinator))}</div><div>Announced</div><div>${d.unannounced ? 'Unannounced' : 'Announced'}</div></div></div></div></div></div>`;
  return { title: d.id, nav: 'emergency', crumbs: [['Emergency Management', '#/emergency/drills'], [d.id, '#']], html }; }
ACT.drillNew = (el) => { const sid = (el && el.dataset && el.dataset.site) || defaultSite(); openModal({ title: 'Schedule an emergency drill', body: `<div class="form-grid">${fld({ name: 'site', label: 'Branch', type: 'select', options: siteOptions(sid, false), required: true })}${fld({ name: 'date', label: 'Date', type: 'date', value: addDays(TODAY, 14), required: true })}${fld({ name: 'scenario', label: 'Scenario', value: 'Fire — full evacuation', required: true, full: true })}${fld({ name: 'coordinator', label: 'Coordinator', type: 'select', options: personOptions((site(sid) || {}).manager, p => !!p.sysRole), required: true })}${fld({ name: 'target', label: 'Target evacuation time (minutes)', type: 'number', min: 1, value: 4 })}${fld({ name: 'unannounced', label: 'Unannounced drill', type: 'checkbox', full: true })}</div>`,
  buttons: [{ label: 'Schedule', cls: 'primary', onClick: m => { if (!validateForm(m)) return false; const v = readForm(m); S.drills = S.drills || []; const d = { id: nextId('DRL-', 'drills'), org: siteOrgOf(v.site), site: v.site, date: v.date, scenario: v.scenario, coordinator: v.coordinator, target: +v.target || null, unannounced: v.unannounced, status: 'Scheduled', findings: [] }; S.drills.push(d);
    queueEmail([v.coordinator], 'actions', `Emergency drill scheduled: ${sname(v.site)} on ${fmt(v.date)}`, `You coordinate the ${v.scenario} drill at ${sname(v.site)} on ${fmt(v.date)}.`, '#/emergency/' + d.id); log(`Scheduled drill ${d.id} at ${sname(v.site)}`, '#/emergency/' + d.id); save(); navigate('#/emergency/' + d.id); } }] }); };
ACT.drillHeld = (el) => { const sid = (el && el.dataset && el.dataset.site) || defaultSite();
  openModal({ title: 'Record a drill already held', sub: 'Step 1 of 2: which drill', body: `<div class="form-grid">${fld({ name: 'site', label: 'Branch', type: 'select', options: siteOptions(sid, false), required: true })}${fld({ name: 'scenario', label: 'Scenario', value: 'Fire — full evacuation', required: true, full: true })}${fld({ name: 'coordinator', label: 'Coordinator', type: 'select', options: personOptions(S.ui.user, p => !!p.sysRole), required: true })}${fld({ name: 'target', label: 'Target evacuation time (minutes)', type: 'number', min: 1, value: 4 })}${fld({ name: 'unannounced', label: 'It was unannounced', type: 'checkbox', full: true })}</div>`,
    buttons: [{ label: 'Next: the result', cls: 'primary', onClick: m => { if (!validateForm(m)) return false; const v = readForm(m); S.drills = S.drills || [];
      const d = { id: nextId('DRL-', 'drills'), org: siteOrgOf(v.site), site: v.site, date: TODAY, scenario: v.scenario, coordinator: v.coordinator, target: +v.target || null, unannounced: v.unannounced, status: 'Scheduled', findings: [] }; S.drills.push(d); save();
      navigate('#/emergency/' + d.id); setTimeout(() => ACT.drillResult({ dataset: { id: d.id } }), 60); } }] }); };
ACT.drillResult = (el) => { const d = byId('drills', el.dataset.id); openModal({ title: 'Record the drill result', size: 'wide', body: `<div class="form-grid">${fld({ name: 'held', label: 'Date held', type: 'date', value: TODAY, required: true })}${fld({ name: 'evacMinutes', label: 'Evacuation time (minutes)', type: 'number', min: 0, required: true })}${fld({ name: 'people', label: 'People evacuated', type: 'number', min: 0, required: true })}${fld({ name: 'observations', label: 'Observations', type: 'textarea', full: true })}${fld({ name: 'findings', label: 'Findings — one per line; each becomes a corrective action', type: 'textarea', rows: 4, full: true })}${fld({ name: 'owner', label: 'Owner of the corrective actions', type: 'select', options: personOptions((site(d.site) || {}).manager, canOwnActions) })}${fld({ name: 'file', label: 'Drill report / photos', type: 'file', full: true })}</div>`,
  buttons: [{ label: 'Save result', cls: 'primary', onClick: m => { if (!validateForm(m)) return false; const v = readForm(m); Object.assign(d, { held: v.held, evacMinutes: +v.evacMinutes, people: +v.people, observations: v.observations, status: 'Completed', files: v.file ? [v.file] : [] });
    d.findings = (v.findings || '').split('\n').map(x => x.trim()).filter(Boolean).map(t => ({ text: t, action: createAction({ source: 'Emergency drill', sourceId: d.id, title: `Drill ${sname(d.site)}: ${t}`.slice(0, 140), action: t, owner: v.owner, priority: 'Medium', site: d.site }).id }));
    if (d.target && d.evacMinutes > d.target) d.findings.push({ text: `Evacuation took ${d.evacMinutes} min, target ${d.target} min`, action: null });
    log(`Recorded drill ${d.id}: ${d.evacMinutes} min, ${d.findings.length} finding(s)`, '#/emergency/' + d.id); save(); rerender(); } }] }); };

/* ---------------- Wiring + demo data ---------------- */
(() => { const g = NAV.find(x => x.group === 'Operational safety'); if (g && !g.items.some(i => i[0] === 'emergency')) g.items.push(['emergency', 'Emergency Management', 'siren']); })();
AREA_OF.emergency = 'area.emergency'; if (!TOP_ROUTES.includes('emergency')) TOP_ROUTES.push('emergency');
if (!SOURCE_MODULES.includes('Emergency drill')) SOURCE_MODULES.splice(SOURCE_MODULES.length - 1, 0, 'Emergency drill');
const _sourceLinkBeforeEm = sourceLink; sourceLink = function (a) { return a.source === 'Emergency drill' && byId('drills', a.sourceId) ? `<a href="#/emergency/${a.sourceId}">${esc(a.sourceId)}</a>` : _sourceLinkBeforeEm(a); };
const _needsBackBeforeEm = needsBack; needsBack = function (parts) { if (parts[0] === 'emergency' && parts[1] && !/^DRL-/.test(parts[1])) return false; return _needsBackBeforeEm(parts); };
